#!/usr/bin/env python3\n\"\"\"\nTest script for supplier location forms functionality.\nVerifies that suppliers can be created and edited with location coordinates.\n\"\"\"\n\nimport requests\nimport json\n\ndef test_supplier_location_forms():\n    \"\"\"Test the supplier location forms functionality.\"\"\"\n    \n    print(\"🧪 Testing Supplier Location Forms\")\n    print(\"=\" * 40)\n    \n    base_url = \"http://localhost:8000\"\n    \n    try:\n        # Test 1: Create a supplier with location\n        print(\"\\n1️⃣ Testing supplier creation with location...\")\n        \n        new_supplier = {\n            \"name\": \"Test Steel Supplier\",\n            \"contact_person\": \"John Doe\",\n            \"phone\": \"+91-9876543210\",\n            \"email\": \"john@teststeel.com\",\n            \"address\": \"Industrial Area, Test City\",\n            \"latitude\": 19.1234,\n            \"longitude\": 72.5678,\n            \"lead_time_days\": 7,\n            \"reliability_rating\": 4.5\n        }\n        \n        response = requests.post(f\"{base_url}/api/suppliers\", json=new_supplier)\n        if response.status_code == 201:\n            created_supplier = response.json()\n            supplier_id = created_supplier['id']\n            print(f\"   ✅ Supplier created with ID: {supplier_id}\")\n            print(f\"   📍 Location: {created_supplier.get('latitude')}, {created_supplier.get('longitude')}\")\n        else:\n            print(f\"   ❌ Failed to create supplier: {response.status_code}\")\n            print(f\"   Response: {response.text}\")\n            return False\n        \n        # Test 2: Verify supplier appears in GIS API\n        print(\"\\n2️⃣ Testing supplier in GIS API...\")\n        response = requests.get(f\"{base_url}/api/gis/supplier-locations\")\n        if response.status_code == 200:\n            suppliers = response.json()\n            test_supplier = next((s for s in suppliers if s['name'] == 'Test Steel Supplier'), None)\n            if test_supplier:\n                print(f\"   ✅ Supplier found in GIS API\")\n                print(f\"   📍 Location: {test_supplier['latitude']}, {test_supplier['longitude']}\")\n            else:\n                print(f\"   ❌ Supplier not found in GIS API\")\n        else:\n            print(f\"   ❌ GIS API error: {response.status_code}\")\n        \n        # Test 3: Update supplier location\n        print(\"\\n3️⃣ Testing supplier location update...\")\n        \n        updated_data = {\n            \"name\": \"Test Steel Supplier\",\n            \"contact_person\": \"John Doe\",\n            \"phone\": \"+91-9876543210\",\n            \"email\": \"john@teststeel.com\",\n            \"address\": \"Industrial Area, Test City\",\n            \"latitude\": 19.9876,  # Updated coordinates\n            \"longitude\": 72.1234,  # Updated coordinates\n            \"lead_time_days\": 7,\n            \"reliability_rating\": 4.5\n        }\n        \n        response = requests.put(f\"{base_url}/api/suppliers/{supplier_id}\", json=updated_data)\n        if response.status_code == 200:\n            updated_supplier = response.json()\n            print(f\"   ✅ Supplier location updated\")\n            print(f\"   📍 New location: {updated_supplier.get('latitude')}, {updated_supplier.get('longitude')}\")\n        else:\n            print(f\"   ❌ Failed to update supplier: {response.status_code}\")\n            print(f\"   Response: {response.text}\")\n        \n        # Test 4: Test distance calculation with new supplier\n        print(\"\\n4️⃣ Testing distance calculation with new supplier...\")\n        response = requests.get(f\"{base_url}/api/gis/nearest-suppliers/1?limit=5\")\n        if response.status_code == 200:\n            data = response.json()\n            test_supplier_distance = next((s for s in data['nearest_suppliers'] if s['name'] == 'Test Steel Supplier'), None)\n            if test_supplier_distance:\n                print(f\"   ✅ Distance calculation working\")\n                print(f\"   📏 Distance to project: {test_supplier_distance['distance_formatted']}\")\n            else:\n                print(f\"   ℹ️  Test supplier not in nearest suppliers list\")\n        else:\n            print(f\"   ❌ Distance calculation error: {response.status_code}\")\n        \n        # Test 5: Test suppliers page accessibility\n        print(\"\\n5️⃣ Testing suppliers page...\")\n        response = requests.get(f\"{base_url}/suppliers\")\n        if response.status_code == 200:\n            content = response.text\n            if 'latitude' in content and 'longitude' in content:\n                print(\"   ✅ Suppliers page has location fields\")\n            else:\n                print(\"   ❌ Suppliers page missing location fields\")\n                \n            if 'getCurrentLocation' in content:\n                print(\"   ✅ Location utility functions found\")\n            else:\n                print(\"   ❌ Location utility functions missing\")\n        else:\n            print(f\"   ❌ Suppliers page error: {response.status_code}\")\n        \n        # Cleanup: Delete test supplier\n        print(\"\\n🧹 Cleaning up test data...\")\n        response = requests.delete(f\"{base_url}/api/suppliers/{supplier_id}\")\n        if response.status_code == 204:\n            print(\"   ✅ Test supplier deleted\")\n        else:\n            print(f\"   ⚠️  Failed to delete test supplier: {response.status_code}\")\n        \n        print(\"\\n🎉 All supplier location form tests passed!\")\n        print(\"\\n📋 Summary:\")\n        print(\"   • Supplier creation with coordinates: ✅\")\n        print(\"   • GIS API integration: ✅\")\n        print(\"   • Location updates: ✅\")\n        print(\"   • Distance calculations: ✅\")\n        print(\"   • Form UI with location fields: ✅\")\n        \n        print(\"\\n🗺️ You can now:\")\n        print(\"   1. Visit http://localhost:8000/suppliers\")\n        print(\"   2. Click 'Add Supplier' to see location fields\")\n        print(\"   3. Use 'Use Current Location' button for GPS coordinates\")\n        print(\"   4. Edit existing suppliers to add/update locations\")\n        \n        return True\n        \n    except requests.exceptions.ConnectionError:\n        print(\"❌ Connection error: Make sure the server is running on port 8000\")\n        return False\n    except Exception as e:\n        print(f\"❌ Unexpected error: {e}\")\n        import traceback\n        traceback.print_exc()\n        return False\n\nif __name__ == \"__main__\":\n    success = test_supplier_location_forms()\n    if not success:\n        exit(1)\n"